let scaleStep = 0;

function applyScaleOp(op) {
    const eq = document.getElementById('scale-eq-display');
    const exp = document.getElementById('scale-step-explanation');
    const pl = document.getElementById('pan-left-val');
    const pr = document.getElementById('pan-right-val');
    const pill = document.getElementById('scale-pill');

    if (op === 'sub6') {
        scaleStep = 1;
        eq.innerText = '2x = 10';
        exp.innerText = 'Subtraction Property of Equality: Subtracted 6 from both pans. The equation simplified to 2x = 10.';
        pl.innerText = '2x';
        pr.innerText = '10';
        pill.innerHTML = '<i class="fas fa-check" style="color:#10b981;"></i> Step 1 Complete: 2x = 10';
    } else if (op === 'div2') {
        if (scaleStep === 0) applyScaleOp('sub6');
        scaleStep = 2;
        eq.innerText = 'x = 5';
        exp.innerText = 'Multiplication Property of Equality: Multiplied both sides by 1/2 (divided by 2). Variable isolated: x = 5.';
        pl.innerText = 'x';
        pr.innerText = '5';
        pill.innerHTML = '<i class="fas fa-star" style="color:#f59e0b;"></i> Solved! Solution Set: {5}';
    }
}

function resetScale() {
    scaleStep = 0;
    document.getElementById('scale-eq-display').innerText = '2x + 6 = 16';
    document.getElementById('scale-step-explanation').innerText = 'Initial state: The left pan holds 2x + 6 and the right pan holds 16.';
    document.getElementById('pan-left-val').innerText = '2x + 6';
    document.getElementById('pan-right-val').innerText = '16';
    document.getElementById('scale-pill').innerHTML = '<i class="fas fa-balance-scale" style="color:#10b981;"></i> Balanced: Both sides are equivalent';
}
